mapper.select:
select mn.* ,u.U_Name as dispatchUname,c.C_Name as constructionContractorName,c2.C_Name as auditUnitName
from annual_plan mn
left join sys_user u on mn.Dispatch_Uid = u.U_ID
left join sys_company c on mn.Construction_Contractor = c.C_ID
left join sys_company c2 on mn.Audit_Unit = c2.C_ID

    
        and mn.year = #{params.year}
    
    
        and mn.con_name like concat('%',#{params.conName},'%')
    
    
        and mn.Create_Time >= #{params.startTime}
    
    
        and mn.Create_Time <= #{params.endTime}
    
    
        and mn.start_Time <= #{params.effectiveDate}
        and mn.end_Time >= #{params.effectiveDate}
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
